urlset:
{# With the site's default paginate_path, /page/1/ redirects to the archive root.
   Keep later pagers and real last-modified dates from Zola's original entries. #}
{%- for entry in entries %}
{%- if not entry.permalink is ending_with(pat="/page/1/") %}

    {{ entry.permalink | escape_xml | safe }}
    {%- if entry.updated %}
    {{ entry.updated }}
    {%- endif %}

{%- endif %}
{%- endfor %}
